"use strict";
/* ============================================================
   发布关口 · Release Gate
   单页 · 零依赖 · 初始数据内联，脚本执行即完成首屏渲染。
   用户任务：零失误走完一次高后果发布流程；
   不可逆步骤 = 确认门（提交前）+ 恢复点（提交后）。
   ============================================================ */

/* ---------------- 内联初始数据（首屏就绪，无任何异步加载） ---------------- */
const WORKFLOW = {
