"use strict";
/* ============================================================
   发布关口 · Release Gate
   单页 · 零依赖 · 初始数据内联，脚本执行即完成首屏渲染。
   用户任务：零失误走完一次高后果发布流程；
   不可逆步骤 = 确认门（提交前）+ 恢复点（提交后）。
   ============================================================ */

/* ---------------- 内联初始数据（首屏就绪，无任何异步加载） ---------------- */
const WORKFLOW = {
  code: "CHG-8842",
  title: "生产发布 · 订单服务 order-service v2.4.0",
  window: "变更窗口 22:00–23:30",
  phases: [
    {
      id: "P1", name: "阶段一 · 预检",
      steps: [
        {
          id: "S1", name: "变更单与预案核对", irreversible: false,
          actionLabel: "完成核验",
