238	      ${s.irreversible ? '<span class="tag is-danger">⚠ 不可逆步骤</span>' : '<span class="tag">可逆步骤</span>'}
239	      ${st === "committed" ? '<span class="tag is-violet">已提交</span>' : st === "done" ? '<span class="tag is-ok">已完成</span>' : st === "locked" ? '<span class="tag is-lock">🔒 锁定</span>' : ""}</div>
