281	      html += `<div class="committed-note">✔ 已提交 · 不可直接撤销。<span class="rp-ref">${rp ? rp.id : "恢复点"}</span>
282	        已就绪，如需回退请使用右侧「恢复点」面板的恢复路径。</div>`;
283	    } else {
284	      html += `<div class="done-note">✔ 本步骤已完成（可逆步骤，如需可按预案重新执行前置检查）。</div>`;
285	    }
286	  }
287	  html += `</div>`;
