334	function renderGate() {
335	  const root = $("#modal-root");
336	  const g = state.gate;
337	  if (!g) { root.innerHTML = ""; document.body.style.overflow = ""; return; }
338	  document.body.style.overflow = "hidden";
339	
340	  if (g.kind === "commit") {
341	    const s = stepById(g.stepId);
342	    root.innerHTML = `<div class="overlay" data-action="gate-overlay">
343	      <div class="gate" role="dialog" aria-modal="true" aria-labelledby="gate-title">
344	        <div class="gate-head">
345	          <div class="gate-kicker">⚠ 确认门 · 不可逆步骤</div>
346	          <h2 id="gate-title">${esc(s.actionLabel)}：${esc(s.name)}</h2>
347	        </div>
348	        <div class="gate-body">
349	          <div class="gate-consequence"><b>提交后不可直接撤销。</b>${esc(s.consequence)}</div>
350	          <div class="gate-checkpoint">提交成功将自动创建恢复点 <span class="rp-ref">RP-${state.seq + 1}</span>（恢复路径：${esc(s.recoveryPlan)}）</div>
351	          <label class="gate-ack"><input type="checkbox" id="gate-ack" data-action="gate-ack">
352	            <span>我已理解上述后果，确认核验清单全部满足、恢复预案可用，<b>有意执行</b>本不可逆操作。</span></label>
353	          <div class="gate-pass">
354	            <label for="gate-pass-input">输入口令 <code>${s.passcode}</code> 以启用提交</label>
355	            <input id="gate-pass-input" type="text" autocomplete="off" spellcheck="false"
356	              placeholder="输入 ${s.passcode}" data-action="gate-pass" aria-describedby="gate-err">
357	            <div class="gate-err" id="gate-err" role="alert"></div>
358	          </div>
359	        </div>
