361	          <button type="button" class="btn btn-ghost" data-action="gate-cancel">取消</button>
362	          <button type="button" class="btn btn-danger" id="gate-confirm" data-action="gate-confirm" disabled>确认提交</button>
363	        </div>
364	      </div></div>`;
365	    $("#gate-ack").focus();
366	  }
367	
368	  if (g.kind === "recover") {
369	    const rp = state.checkpoints.find(c => c.id === g.rpId);
370	    root.innerHTML = `<div class="overlay" data-action="gate-overlay">
371	      <div class="gate is-recover" role="dialog" aria-modal="true" aria-labelledby="gate-title">
372	        <div class="gate-head">
373	          <div class="gate-kicker">↺ 恢复确认 · Recovery Gate</div>
374	          <h2 id="gate-title">从恢复点 ${rp.id} 恢复？</h2>
375	        </div>
376	        <div class="gate-body">
377	          <div class="gate-consequence">流程状态将回退到 <b>${esc(rp.stepName)}（${rp.actionLabel}）提交之前</b>：
378	            其后所有已提交步骤将回到待执行状态，其核验勾选将还原；本操作会记入执行记录。</div>
379	          <label class="gate-ack"><input type="checkbox" id="gate-ack" data-action="gate-ack">
380	            <span>我确认执行恢复，并理解其后已提交的步骤需要重新执行。</span></label>
381	          <div class="gate-err" id="gate-err" role="alert"></div>
382	        </div>
383	        <div class="gate-foot">
384	          <button type="button" class="btn btn-ghost" data-action="gate-cancel">取消</button>
385	          <button type="button" class="btn btn-danger" id="gate-confirm" data-action="gate-confirm" disabled>确认恢复</button>
386	        </div>
387	      </div></div>`;
388	    $("#gate-ack").focus();
389	  }
390	
391	  if (g.kind === "reset") {
392	    root.innerHTML = `<div class="overlay" data-action="gate-overlay">
393	      <div class="gate is-reset" role="dialog" aria-modal="true" aria-labelledby="gate-title">
394	        <div class="gate-head">
395	          <div class="gate-kicker">⟲ 重启演练</div>
396	          <h2 id="gate-title">重置整个流程到初始态？</h2>
397	        </div>
398	        <div class="gate-body">
399	          <div class="gate-consequence">当前演练的全部进度、${state.checkpoints.length} 个恢复点与执行记录将被清空，流程回到第一步。此操作不可撤销。</div>
400	          <label class="gate-ack"><input type="checkbox" id="gate-ack" data-action="gate-ack">
401	            <span>我确认丢弃当前演练进度并重新开始。</span></label>
402	          <div class="gate-pass">
403	            <label for="gate-pass-input">输入口令 <code>RESET</code> 以启用重置</label>
404	            <input id="gate-pass-input" type="text" autocomplete="off" spellcheck="false"
405	              placeholder="输入 RESET" data-action="gate-pass" aria-describedby="gate-err">
406	            <div class="gate-err" id="gate-err" role="alert"></div>
407	          </div>
408	        </div>
409	        <div class="gate-foot">
410	          <button type="button" class="btn btn-ghost" data-action="gate-cancel">取消</button>
411	          <button type="button" class="btn btn-danger" id="gate-confirm" data-action="gate-confirm" disabled>确认重置</button>
412	        </div>
413	      </div></div>`;
414	    $("#gate-ack").focus();
415	  }
416	}
417	
418	/* 口令/勾选变化 → 仅同步提交按钮可用性（不整屏重渲染，保持输入焦点） */
419	function syncGateButton() {
420	  const g = state.gate;
421	  if (!g) return;
422	  const btn = $("#gate-confirm");
423	  const err = $("#gate-err");
424	  if (!btn) return;
425	  const ack = $("#gate-ack").checked;
426	  let passOk = true;
427	  if (g.kind === "commit") passOk = $("#gate-pass-input").value.trim() === stepById(g.stepId).passcode;
428	  if (g.kind === "reset") passOk = $("#gate-pass-input").value.trim() === "RESET";
429	  const ok = ack && passOk;
430	  btn.disabled = !ok;
431	  if (!ack) { err.textContent = ""; }
432	  else if (!passOk) { err.textContent = "口令不匹配——请核对括号中的口令原文（这是防误触的最后一道闸）。"; }
433	  else { err.textContent = ""; }
434	}
435	
436	/* ---------------- 动作 ---------------- */
437	function commitStep(stepId) {
438	  const s = stepById(stepId);
439	  if (!isOpen(s) || !checksAllDone(s)) return;
440	  state.done[stepId].finished = true;
441	  if (s.irreversible) {
442	    state.seq += 1;
443	    const snapshot = structuredClone({ done: state.done, completedAt: state.completedAt });
444	    state.checkpoints.push({
445	      id: "RP-" + state.seq, seq: state.seq, stepId: s.id,
446	      stepName: s.name, actionLabel: s.actionLabel, at: now(),
447	      snapshot, superseded: false
448	    });
449	    log("commit", `已通过确认门提交「${s.name}」（口令 ${s.passcode}）· 自动创建恢复点 RP-${state.seq}`);
450	    toast(`已提交：${s.name} · 恢复点 RP-${state.seq} 已创建`, "violet");
451	  } else {
452	    log("check", `已完成可逆步骤「${s.name}」（${s.actionLabel}）`);
453	    toast(`已完成：${s.name}`);
454	  }
455	  if (s.final) {
456	    state.completedAt = Date.now();
457	    log("note", `流程完成 · 零失误走完全程（用时 ${elapsed(state.completedAt - state.startedAt)}）`);
458	  }
459	  // 推进选择到下一个未完成步骤
460	  const next = ALL_STEPS.find(x => !state.done[x.id].finished);
461	  state.selected = next ? next.id : s.id;
462	  render();
463	  const btn = $("#btn-primary");
464	  if (btn && !btn.disabled) btn.focus();
465	}
466	
467	function doRecover(rpId) {
468	  const rp = state.checkpoints.find(c => c.id === rpId);
469	  if (!rp || rp.superseded) return;
470	  state.done = structuredClone(rp.snapshot.done);
471	  state.completedAt = rp.snapshot.completedAt;
472	  state.checkpoints.forEach(c => { if (c.seq > rp.seq) c.superseded = true; });
473	  const next = ALL_STEPS.find(x => !state.done[x.id].finished);
474	  state.selected = next ? next.id : rp.stepId;
475	  log("recover", `已从恢复点 ${rp.id} 恢复 · 流程回退到「${rp.stepName}」提交前，其后提交已回退`);
476	  toast(`已从 ${rp.id} 恢复 · 流程回退到「${rp.stepName}」提交前`, "violet");
477	  render();
478	}
479	
480	function doReset() {
481	  const stats = `${checkedCount()} 项核验 · ${state.checkpoints.length} 个恢复点`;
482	  state = freshState();
483	  log("reset", `演练已重置（丢弃 ${stats}），流程回到初始态`);
484	  render();
485	  toast("演练已重置，流程回到第一步", "warn");
486	}
487	
488	/* ---------------- 事件（委托） ---------------- */
489	document.addEventListener("click", e => {
490	  const el = e.target.closest("[data-action]");
491	  if (!el) {
492	    if (state.gate && e.target.classList && e.target.classList.contains("overlay")) closeGate();
493	    return;
494	  }
495	  const act = el.dataset.action;
496	  if (act === "gate-overlay") {
497	    if (e.target === el) closeGate();  // 仅点击遮罩本身关闭，点击对话框内部不关闭
498	    return;
499	  }
500	  if (act === "select") {
501	    state.selected = el.dataset.step;
502	    render();
503	  }
504	  if (act === "toggle-check") {
505	    const s = stepById(el.dataset.step);
506	    if (!isOpen(s) || state.done[s.id].finished) return;
507	    const i = Number(el.dataset.idx);
508	    const on = !state.done[s.id].checks[i];
509	    state.done[s.id].checks[i] = on;
510	    log("check", `${on ? "勾选" : "取消"}核验「${s.checks[i]}」（${s.name}）`);
511	    render();
512	  }
513	  if (act === "commit") commitStep(el.dataset.step);
514	  if (act === "open-commit-gate") {
515	    const s = stepById(el.dataset.step);
516	    if (!isOpen(s) || !checksAllDone(s)) return;
517	    openGate({ kind: "commit", stepId: s.id }, el.id || null);
518	  }
519	  if (act === "open-recover-gate") openGate({ kind: "recover", rpId: el.dataset.rp }, "btn-primary");
520	  if (act === "open-reset") openGate({ kind: "reset" }, "btn-reset");
521	  if (act === "gate-cancel") closeGate();
522	  if (act === "gate-confirm") {
523	    const g = state.gate;
524	    if (!g) return;
525	    if (g.kind === "commit") { state.gate = null; commitStep(g.stepId); }
526	    else if (g.kind === "recover") { state.gate = null; doRecover(g.rpId); }
527	    else if (g.kind === "reset") { state.gate = null; doReset(); }
528	  }
529	});
530	
531	document.addEventListener("change", e => {
532	  if (e.target.matches('[data-action="gate-ack"]')) syncGateButton();
533	});
534	document.addEventListener("input", e => {
535	  if (e.target.matches('[data-action="gate-pass"]')) syncGateButton();
536	});
537	document.addEventListener("keydown", e => {
538	  if (e.key === "Escape" && state.gate) { closeGate(); return; }
539	  if (e.key === "Enter" && state.gate) {
540	    const btn = $("#gate-confirm");
541	    if (btn && !btn.disabled && e.target.id === "gate-pass-input") { e.preventDefault(); btn.click(); }
542	    return;
543	  }
544	  // 导航器方向键：↑/↓ 在步骤间移动选择（键盘等价路径）
545	  if ((e.key === "ArrowDown" || e.key === "ArrowUp") && !state.gate) {
546	    const item = e.target.closest(".step-item");
547	    if (!item) return;
548	    e.preventDefault();
549	    const idx = ALL_STEPS.findIndex(s => s.id === item.dataset.step);
550	    const nextIdx = e.key === "ArrowDown" ? Math.min(ALL_STEPS.length - 1, idx + 1) : Math.max(0, idx - 1);
551	    state.selected = ALL_STEPS[nextIdx].id;
552	    render();
553	    const btn = document.querySelector(`.step-item[data-step="${state.selected}"]`);
554	    if (btn) btn.focus();
555	  }
556	});
557	
558	// 恢复点悬停预览 → 导航器高亮来源步骤（preview state）
559	document.addEventListener("mouseover", e => {
560	  const card = e.target.closest("[data-rp]");
561	  const id = card ? card.dataset.rp : null;
562	  if (id !== state.previewRp) {
563	    state.previewRp = id;
564	    renderNav();
565	  }
566	});
567	document.addEventListener("mouseout", e => {
568	  if (e.target.closest && e.target.closest("[data-rp]") && state.previewRp) {
569	    state.previewRp = null;
570	    renderNav();
571	  }
572	});
573	
574	/* ---------------- 首屏：脚本执行即同步渲染，页面加载完成即为可用状态 ---------------- */
575	render();
576

