  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = e => rej(new Error('ws error')); });
  ws.onmessage = e => onMessage(typeof e.data === 'string' ? e.data : e.data.toString());

  await send('Runtime.enable');
