  assert('badges 恢复点 1 可用', b[2] === '恢复点 1 可用', '恢复点 1 可用', b[2]);
  await badgeLine(); await consoleLine();

  /* ---------------- M7: re-commit S4, S5 gate, S6 direct, S7 final gate -> 07-final-gate ---------------- */
