          ]
        }
      ]
    },
    {
      id: "P2", name: "阶段二 · 发布执行",
      steps: [
        {
          id: "S3", name: "灰度发布（5% 流量）", irreversible: false,
          actionLabel: "开始灰度",
          why: "先放 5% 真实流量试水。此步可逆：流量可即时切回 v2.3.9，不产生持久性变更。",
          checks: [
            "灰度批次实例健康检查通过",
            "5% 流量下错误率 < 0.1% 且持续 10 分钟",
