  background: var(--lock-bg); color: var(--ink-2);
  font-size: 11px; font-weight: 700;
}
.phase-label.is-open .phase-idx { background: var(--accent-bg); color: var(--accent); }
.phase-label.is-done .phase-idx { background: var(--ok-bg); color: var(--ok); }

.step-item {
  display: flex; align-items: center; gap: 10px;
  width: 100%;
  padding: 10px 10px;
  margin: 2px 0;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  text-align: left;
  color: var(--ink);
  transition: background .12s ease;
}
.step-item:hover { background: var(--surface-2); }
.step-item.is-selected { background: var(--accent-bg); border-color: #c8d7f8; }
.step-item.is-locked .st-name { color: #4e5d76; font-weight: 500; }
.step-item .st-icon {
  flex: none;
  width: 24px; height: 24px;
  display: grid; place-items: center;
  border-radius: 50%;
  font-size: 12px; font-weight: 700;
  background: var(--lock-bg); color: var(--ink-2);
  border: 1.5px solid var(--line-strong);
}
.step-item.is-active .st-icon { background: #fff; color: var(--accent); border-color: var(--accent); }
.step-item.is-done .st-icon { background: var(--ok); color: #fff; border-color: var(--ok); }
.step-item.is-committed .st-icon { background: var(--violet); color: #fff; border-color: var(--violet); }
.step-item .st-body { flex: 1; min-width: 0; }
.step-item .st-name { display: block; font-weight: 550; font-size: 13.5px; }
.step-item .st-meta { display: block; font-size: 11.5px; color: var(--ink-3); }
.step-item .st-flag {
  flex: none;
  font-size: 11px; font-weight: 700;
  color: var(--danger);
  background: var(--danger-bg);
  border: 1px solid var(--danger-line);
  padding: 1px 7px; border-radius: 999px;
}
.step-item .st-rp {
  flex: none;
  font-size: 10.5px; font-weight: 700;
  color: var(--violet);
  background: var(--violet-bg);
  border: 1px solid var(--violet-line);
  padding: 1px 6px; border-radius: 999px;
  font-family: var(--mono);
}

/* ---------------- 中栏：步骤详情（dominant workspace） ---------------- */
.detail { overflow-y: auto; padding: 26px 34px 48px; }
.detail-inner { max-width: 720px; margin: 0 auto; }

.crumb { font-size: 12.5px; color: var(--ink-3); display: flex; gap: 8px; align-items: center; }
.detail h1 { font-size: 22px; margin: 8px 0 4px; letter-spacing: -.01em; }
.title-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.tag {
  font-size: 11.5px; font-weight: 700;
  padding: 2px 9px; border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--ink-2); background: var(--surface-2);
}
.tag.is-danger { color: var(--danger); background: var(--danger-bg); border-color: var(--danger-line); }
.tag.is-ok { color: var(--ok); background: var(--ok-bg); border-color: var(--ok-line); }
.tag.is-violet { color: var(--violet); background: var(--violet-bg); border-color: var(--violet-line); }
.tag.is-lock { color: var(--ink-3); background: var(--lock-bg); }

.why { color: var(--ink-2); margin: 10px 0 22px; max-width: 62ch; }

.section-label {
  font-size: 12.5px; font-weight: 700; letter-spacing: .05em;
  color: var(--ink-3); text-transform: uppercase;
  margin: 22px 0 10px;
  display: flex; align-items: center; gap: 8px;
}
.section-label .count { font-variant-numeric: tabular-nums; }

.checks { display: flex; flex-direction: column; gap: 8px; }
.check {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 12px 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow-1);
  cursor: pointer;
}
.check:hover { border-color: var(--line-strong); }
.check input { margin: 0; width: 24px; height: 24px; accent-color: var(--accent); flex: none; cursor: pointer; }
.check .check-text { flex: 1; }
.check.is-checked .check-text { color: var(--ink-2); text-decoration: line-through; text-decoration-color: rgba(23,32,46,.25); }
.check.is-disabled { cursor: not-allowed; }
.check.is-disabled .check-text { color: var(--ink-2); }

/* 不可逆后果面板 */
.consequence {
  margin-top: 4px;
  border: 1px solid var(--warn-line);
  background: var(--warn-bg);
  border-radius: var(--radius);
  padding: 14px 16px;
}
.consequence h3 { font-size: 13.5px; color: var(--warn); display: flex; gap: 8px; align-items: center; }
.consequence p { margin: 8px 0 0; font-size: 13.5px; color: #5c4318; }
.consequence .recovery-hint {
  margin-top: 10px; padding-top: 10px;
  border-top: 1px dashed var(--warn-line);
  font-size: 13px; color: #5c4318;
}
.consequence .recovery-hint b { color: var(--warn); }

/* 操作区 */
.action-row {
  margin-top: 26px; padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
}
.btn {
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  padding: 10px 20px;
  font-weight: 600;
  font-size: 14px;
  transition: filter .12s ease, background .12s ease;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover:not(:disabled) { filter: brightness(1.08); }
.btn-primary:disabled { background: var(--lock-bg); color: var(--ink-3); cursor: not-allowed; border-color: var(--line); }
.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover:not(:disabled) { filter: brightness(1.06); }
.btn-danger:disabled { background: var(--danger-bg); color: #8a3d3d; cursor: not-allowed; border-color: var(--danger-line); }
.btn-ghost { background: none; border-color: var(--line-strong); color: var(--ink-2); padding: 8px 14px; font-size: 13px; }
.btn-ghost:hover { background: var(--surface-2); }
.action-hint { font-size: 12.5px; color: var(--ink-3); }

.done-note, .committed-note {
  margin-top: 26px;
  border-radius: var(--radius);
  padding: 14px 16px;
  font-size: 13.5px;
  display: flex; gap: 10px; align-items: flex-start;
}
.done-note { background: var(--ok-bg); border: 1px solid var(--ok-line); color: var(--ok); }
.committed-note { background: var(--violet-bg); border: 1px solid var(--violet-line); color: var(--violet); }
.committed-note .rp-ref { font-family: var(--mono); font-weight: 700; }
.locked-note {
  margin-top: 26px;
  background: var(--lock-bg); border: 1px solid var(--line);
  color: var(--ink-2); border-radius: var(--radius);
  padding: 14px 16px; font-size: 13.5px;
}

/* 完成横幅 */
.complete-banner {
  margin-bottom: 26px;
  border: 1px solid var(--ok-line);
  background: linear-gradient(180deg, #f2faf5, #e9f5ee);
  border-radius: 14px;
  padding: 22px 24px;
}
.complete-banner h2 { font-size: 19px; color: var(--ok); display: flex; gap: 10px; align-items: center; }
.complete-banner p { margin: 8px 0 0; color: var(--ink-2); max-width: 60ch; }
.complete-stats { display: flex; gap: 12px; margin-top: 16px; flex-wrap: wrap; }
.stat-chip {
  background: var(--surface);
  border: 1px solid var(--ok-line);
  border-radius: var(--radius-sm);
  padding: 8px 14px;
  font-size: 12.5px; color: var(--ink-2);
}
.stat-chip b { display: block; font-size: 16px; color: var(--ink); font-variant-numeric: tabular-nums; }

/* ---------------- 右栏：恢复点 + 执行记录 ---------------- */
.side {
  background: var(--surface);
  border-left: 1px solid var(--line);
  display: flex; flex-direction: column;
  min-height: 0;
}
.side-panel { padding: 14px 16px 10px; border-bottom: 1px solid var(--line); overflow-y: auto; }
.side-panel-grow { flex: 1; border-bottom: none; }
.side-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 10px; }
.side-head h2 { font-size: 13px; letter-spacing: .06em; color: var(--ink-3); text-transform: uppercase; }
.side-note { font-size: 11.5px; color: var(--ink-3); }

.rp-card {
  border: 1px solid var(--violet-line);
  background: var(--violet-bg);
  border-radius: var(--radius);
  padding: 11px 13px;
  margin-bottom: 9px;
}
.rp-card.is-superseded { opacity: .55; background: var(--surface-2); border-color: var(--line); }
.rp-top { display: flex; align-items: center; gap: 8px; }
.rp-id { font-family: var(--mono); font-weight: 700; font-size: 13px; color: var(--violet); }
.rp-card.is-superseded .rp-id { color: var(--ink-3); }
.rp-step { font-size: 12px; color: var(--ink-2); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rp-time { font-size: 11.5px; color: var(--ink-3); font-variant-numeric: tabular-nums; margin-top: 3px; display: block; }
.rp-actions { margin-top: 9px; display: flex; align-items: center; gap: 8px; }
.btn-recover {
  font-size: 12.5px; font-weight: 600;
  padding: 5px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--violet);
  background: #fff; color: var(--violet);
}
.btn-recover:hover:not(:disabled) { background: var(--violet); color: #fff; }
.btn-recover:disabled { border-color: var(--line-strong); color: var(--lock); cursor: not-allowed; background: none; }
.rp-mark { font-size: 11.5px; color: var(--ink-3); }
.rp-empty, .ledger-empty {
  color: var(--ink-3);
  font-size: 12.5px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  padding: 14px;
  text-align: center;
  background: var(--surface-2);
}

.ledger { list-style: none; margin: 0; padding: 0; }
.ledger li {
  display: flex; gap: 10px;
  padding: 8px 2px;
  border-bottom: 1px dashed var(--line);
  font-size: 12.5px;
  align-items: flex-start;
}
.ledger li:last-child { border-bottom: none; }
.ledger .lg-icon { flex: none; width: 18px; text-align: center; }
.ledger .lg-body { flex: 1; color: var(--ink-2); }
.ledger .lg-time { display: block; font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
.ledger .is-recover .lg-body { color: var(--violet); }
.ledger .is-commit .lg-body { color: var(--ink); font-weight: 550; }
.ledger .is-reset .lg-body { color: var(--warn); }

/* ---------------- 确认门模态 ---------------- */
.overlay {
  position: fixed; inset: 0;
  background: rgba(15, 22, 34, .46);
  display: grid; place-items: center;
  z-index: 50;
  animation: fade .16s ease;
}
.gate {
  width: min(560px, calc(100vw - 48px));
  max-height: calc(100dvh - 64px);
  overflow-y: auto;
  background: var(--surface);
  border-radius: 14px;
  box-shadow: var(--shadow-2);
  border-top: 4px solid var(--danger);
  animation: rise .18s ease;
}
.gate.is-recover { border-top-color: var(--violet); }
.gate.is-reset { border-top-color: var(--warn); }
.gate-head { padding: 20px 24px 0; }
.gate-kicker {
  font-size: 11.5px; font-weight: 800; letter-spacing: .12em;
  text-transform: uppercase; color: var(--danger);
  display: flex; align-items: center; gap: 8px;
}
.gate.is-recover .gate-kicker { color: var(--violet); }
.gate.is-reset .gate-kicker { color: var(--warn); }
.gate-head h2 { font-size: 19px; margin-top: 6px; }
.gate-body { padding: 14px 24px 4px; }
.gate-consequence {
  background: var(--danger-bg);
  border: 1px solid var(--danger-line);
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  font-size: 13.5px; color: #6b1515;
}
.gate.is-recover .gate-consequence, .gate.is-reset .gate-consequence { background: var(--surface-2); border-color: var(--line); color: var(--ink-2); }
.gate-consequence b { color: var(--danger); }
.gate.is-recover .gate-consequence b { color: var(--violet); }
.gate-checkpoint {
  margin-top: 10px;
  font-size: 13px; color: var(--ink-2);
  display: flex; gap: 8px; align-items: center;
}
.gate-checkpoint .rp-ref { font-family: var(--mono); font-weight: 700; color: var(--violet); }
.gate-ack {
  display: flex; gap: 10px; align-items: flex-start;
  margin-top: 14px;
  font-size: 13.5px;
  cursor: pointer;
}
.gate-ack input { width: 16px; height: 16px; margin-top: 2px; accent-color: var(--danger); flex: none; cursor: pointer; }
.gate-pass { margin-top: 14px; }
.gate-pass label { display: block; font-size: 12.5px; font-weight: 650; color: var(--ink-2); margin-bottom: 6px; }
.gate-pass label code {
  font-family: var(--mono); color: var(--danger);
  background: var(--danger-bg); border: 1px solid var(--danger-line);
  padding: 0 6px; border-radius: 4px;
}
.gate-pass input {
  width: 100%;
  font-family: var(--mono);
  font-size: 15px;
  padding: 9px 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
}
.gate-pass input:focus { border-color: var(--accent); }
.gate-err { margin-top: 6px; font-size: 12px; color: var(--danger); min-height: 16px; }
.gate-foot {
  display: flex; justify-content: flex-end; gap: 10px;
  padding: 16px 24px 20px;
}
@keyframes fade { from { opacity: 0; } }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } }

/* ---------------- Toast ---------------- */
.toast {
  position: fixed; left: 50%; bottom: 26px;
  transform: translateX(-50%) translateY(16px);
  background: var(--ink); color: #fff;
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 13.5px;
  box-shadow: var(--shadow-2);
  opacity: 0; pointer-events: none;
  transition: opacity .18s ease, transform .18s ease;
  z-index: 60;
  max-width: min(620px, calc(100vw - 40px));
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast.is-warn { background: var(--warn); }
.toast.is-violet { background: var(--violet); }

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

@media (max-width: 1100px) {
  body { overflow: auto; height: auto; }
  .shell { grid-template-columns: 1fr; }
  .nav, .detail, .side { border: none; border-bottom: 1px solid var(--line); }
}

/* ============================================================
   发布关口 · Release Gate — spacious 控制台风格
   token 层（CSS 变量）→ 组件层，无外部依赖
   ============================================================ */
:root {
  --bg: #f3f5f8;
  --surface: #ffffff;
  --surface-2: #f8fafc;
  --ink: #17202e;
  --ink-2: #45536b;
  --ink-3: #5d6b82;
  --line: #e2e7ef;
  --line-strong: #cbd4e1;

  --accent: #2557d6;
  --accent-bg: #edf2fe;
  --ok: #17703a;
  --ok-bg: #e9f5ee;
  --ok-line: #bfe3cc;
  --warn: #9a4a08;
  --warn-bg: #fdf3e4;
  --warn-line: #f2d9ae;
  --danger: #b91f1f;
  --danger-bg: #fdeeee;
  --danger-line: #f3c6c6;
  --lock: #97a3b6;
  --lock-bg: #f1f3f7;
  --violet: #5b2fb8;
  --violet-bg: #f2ecfd;
  --violet-line: #ddccf7;

  --radius: 10px;
  --radius-sm: 7px;
  --shadow-1: 0 1px 2px rgba(23, 32, 46, .05), 0 1px 6px rgba(23, 32, 46, .04);
  --shadow-2: 0 8px 30px rgba(23, 32, 46, .16);

  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif;
  --mono: "Cascadia Code", Consolas, "JetBrains Mono", monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 14.5px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  display: grid;
  grid-template-rows: auto 1fr;
  height: 100dvh;
  overflow: hidden;
}

h1, h2, h3 { margin: 0; font-weight: 650; }
button { font-family: inherit; font-size: inherit; cursor: pointer; }
button:focus-visible, a:focus-visible, input:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------------- 顶栏：整体进度与完整性 ---------------- */
.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 12px 22px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
.brand-mark {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  background: var(--ink); color: #fff;
  border-radius: 9px; font-size: 18px;
}
.brand-text { display: flex; flex-direction: column; line-height: 1.25; }
.brand-text strong { font-size: 16px; }
.brand-sub { font-size: 12.5px; color: var(--ink-2); }

.badges { display: flex; gap: 10px; flex-wrap: wrap; margin-left: auto; }
.badge {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  font-size: 12.5px;
  color: var(--ink-2);
  white-space: nowrap;
}
.badge b { color: var(--ink); font-weight: 650; font-variant-numeric: tabular-nums; }
.badge .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--lock); }
.badge.is-ok .dot { background: var(--ok); }
.badge.is-violet .dot { background: var(--violet); }
.badge.is-warn .dot { background: var(--warn); }
.badge.is-accent .dot { background: var(--accent); }

/* ---------------- 三栏骨架 ---------------- */
.shell {
  display: grid;
  grid-template-columns: 296px minmax(0, 1fr) 328px;
  min-height: 0;
}

/* ---------------- 左栏：阶段→步骤导航器 ---------------- */
.nav {
  background: var(--surface);
  border-right: 1px solid var(--line);
  overflow-y: auto;
  padding: 14px 12px 24px;
}
.nav-head {
  display: flex; align-items: baseline; justify-content: space-between;
  padding: 2px 8px 10px;
}
.nav-head h2 { font-size: 13px; letter-spacing: .06em; color: var(--ink-3); text-transform: uppercase; }
.nav-hint { font-size: 12px; color: var(--ink-3); font-variant-numeric: tabular-nums; }

.phase-label {
  display: flex; align-items: center; gap: 8px;
  margin: 16px 8px 6px;
  font-size: 12.5px; font-weight: 650; color: var(--ink-2);
}
.phase-label .phase-line { flex: 1; height: 1px; background: var(--line); }
.phase-label .phase-idx {
  width: 20px; height: 20px; border-radius: 6px;
  display: grid; place-items: center;
  background: var(--lock-bg); color: var(--ink-2);
  font-size: 11px; font-weight: 700;
}
.phase-label.is-open .phase-idx { background: var(--accent-bg); color: var(--accent); }
.phase-label.is-done .phase-idx { background: var(--ok-bg); color: var(--ok); }

.step-item {
  display: flex; align-items: center; gap: 10px;
  width: 100%;
  padding: 10px 10px;
  margin: 2px 0;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  text-align: left;
  color: var(--ink);
  transition: background .12s ease;
}
.step-item:hover { background: var(--surface-2); }
.step-item.is-selected { background: var(--accent-bg); border-color: #c8d7f8; }
.step-item.is-locked .st-name { color: #4e5d76; font-weight: 500; }
.step-item .st-icon {
  flex: none;
  width: 24px; height: 24px;
  display: grid; place-items: center;
  border-radius: 50%;
  font-size: 12px; font-weight: 700;
  background: var(--lock-bg); color: var(--ink-2);
  border: 1.5px solid var(--line-strong);
}
.step-item.is-active .st-icon { background: #fff; color: var(--accent); border-color: var(--accent); }
.step-item.is-done .st-icon { background: var(--ok); color: #fff; border-color: var(--ok); }
.step-item.is-committed .st-icon { background: var(--violet); color: #fff; border-color: var(--violet); }
.step-item .st-body { flex: 1; min-width: 0; }
.step-item .st-name { display: block; font-weight: 550; font-size: 13.5px; }
.step-item .st-meta { display: block; font-size: 11.5px; color: var(--ink-3); }
.step-item .st-flag {
  flex: none;
  font-size: 11px; font-weight: 700;
  color: var(--danger);
  background: var(--danger-bg);
  border: 1px solid var(--danger-line);
  padding: 1px 7px; border-radius: 999px;
}
.step-item .st-rp {
  flex: none;
  font-size: 10.5px; font-weight: 700;
  color: var(--violet);
  background: var(--violet-bg);
  border: 1px solid var(--violet-line);
  padding: 1px 6px; border-radius: 999px;
  font-family: var(--mono);
}

/* ---------------- 中栏：步骤详情（dominant workspace） ---------------- */
.detail { overflow-y: auto; padding: 26px 34px 48px; }
.detail-inner { max-width: 720px; margin: 0 auto; }

.crumb { font-size: 12.5px; color: var(--ink-3); display: flex; gap: 8px; align-items: center; }
.detail h1 { font-size: 22px; margin: 8px 0 4px; letter-spacing: -.01em; }
.title-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.tag {
  font-size: 11.5px; font-weight: 700;
  padding: 2px 9px; border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--ink-2); background: var(--surface-2);
}
.tag.is-danger { color: var(--danger); background: var(--danger-bg); border-color: var(--danger-line); }
.tag.is-ok { color: var(--ok); background: var(--ok-bg); border-color: var(--ok-line); }
.tag.is-violet { color: var(--violet); background: var(--violet-bg); border-color: var(--violet-line); }
.tag.is-lock { color: var(--ink-3); background: var(--lock-bg); }

.why { color: var(--ink-2); margin: 10px 0 22px; max-width: 62ch; }

.section-label {
  font-size: 12.5px; font-weight: 700; letter-spacing: .05em;
  color: var(--ink-3); text-transform: uppercase;
  margin: 22px 0 10px;
  display: flex; align-items: center; gap: 8px;
}
.section-label .count { font-variant-numeric: tabular-nums; }

.checks { display: flex; flex-direction: column; gap: 8px; }
.check {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 12px 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow-1);
  cursor: pointer;
}
.check:hover { border-color: var(--line-strong); }
.check input { margin: 0; width: 24px; height: 24px; accent-color: var(--accent); flex: none; cursor: pointer; }
.check .check-text { flex: 1; }
.check.is-checked .check-text { color: var(--ink-2); text-decoration: line-through; text-decoration-color: rgba(23,32,46,.25); }
.check.is-disabled { cursor: not-allowed; }
.check.is-disabled .check-text { color: var(--ink-2); }

/* 不可逆后果面板 */
.consequence {
  margin-top: 4px;
  border: 1px solid var(--warn-line);
  background: var(--warn-bg);
  border-radius: var(--radius);
  padding: 14px 16px;
}
.consequence h3 { font-size: 13.5px; color: var(--warn); display: flex; gap: 8px; align-items: center; }
.consequence p { margin: 8px 0 0; font-size: 13.5px; color: #5c4318; }
.consequence .recovery-hint {
  margin-top: 10px; padding-top: 10px;
  border-top: 1px dashed var(--warn-line);
  font-size: 13px; color: #5c4318;
}
.consequence .recovery-hint b { color: var(--warn); }

/* 操作区 */
.action-row {
  margin-top: 26px; padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
}
.btn {
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  padding: 10px 20px;
  font-weight: 600;
  font-size: 14px;
  transition: filter .12s ease, background .12s ease;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover:not(:disabled) { filter: brightness(1.08); }
.btn-primary:disabled { background: var(--lock-bg); color: var(--ink-3); cursor: not-allowed; border-color: var(--line); }
.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover:not(:disabled) { filter: brightness(1.06); }
.btn-danger:disabled { background: var(--danger-bg); color: #8a3d3d; cursor: not-allowed; border-color: var(--danger-line); }
.btn-ghost { background: none; border-color: var(--line-strong); color: var(--ink-2); padding: 8px 14px; font-size: 13px; }
.btn-ghost:hover { background: var(--surface-2); }
.action-hint { font-size: 12.5px; color: var(--ink-3); }

.done-note, .committed-note {
  margin-top: 26px;
  border-radius: var(--radius);
  padding: 14px 16px;
  font-size: 13.5px;
  display: flex; gap: 10px; align-items: flex-start;
}
.done-note { background: var(--ok-bg); border: 1px solid var(--ok-line); color: var(--ok); }
.committed-note { background: var(--violet-bg); border: 1px solid var(--violet-line); color: var(--violet); }
.committed-note .rp-ref { font-family: var(--mono); font-weight: 700; }
.locked-note {
  margin-top: 26px;
  background: var(--lock-bg); border: 1px solid var(--line);
  color: var(--ink-2); border-radius: var(--radius);
  padding: 14px 16px; font-size: 13.5px;
}

/* 完成横幅 */
.complete-banner {
  margin-bottom: 26px;
  border: 1px solid var(--ok-line);
  background: linear-gradient(180deg, #f2faf5, #e9f5ee);
  border-radius: 14px;
  padding: 22px 24px;
}
.complete-banner h2 { font-size: 19px; color: var(--ok); display: flex; gap: 10px; align-items: center; }
.complete-banner p { margin: 8px 0 0; color: var(--ink-2); max-width: 60ch; }
.complete-stats { display: flex; gap: 12px; margin-top: 16px; flex-wrap: wrap; }
.stat-chip {
  background: var(--surface);
  border: 1px solid var(--ok-line);
  border-radius: var(--radius-sm);
  padding: 8px 14px;
  font-size: 12.5px; color: var(--ink-2);
}
.stat-chip b { display: block; font-size: 16px; color: var(--ink); font-variant-numeric: tabular-nums; }

/* ---------------- 右栏：恢复点 + 执行记录 ---------------- */
.side {
  background: var(--surface);
  border-left: 1px solid var(--line);
  display: flex; flex-direction: column;
  min-height: 0;
}
.side-panel { padding: 14px 16px 10px; border-bottom: 1px solid var(--line); overflow-y: auto; }
.side-panel-grow { flex: 1; border-bottom: none; }
.side-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 10px; }
.side-head h2 { font-size: 13px; letter-spacing: .06em; color: var(--ink-3); text-transform: uppercase; }
.side-note { font-size: 11.5px; color: var(--ink-3); }

.rp-card {
  border: 1px solid var(--violet-line);
  background: var(--violet-bg);
  border-radius: var(--radius);
  padding: 11px 13px;
  margin-bottom: 9px;
}
.rp-card.is-superseded { background: var(--surface-2); border-color: var(--line); }
.rp-card.is-superseded .rp-id,
.rp-card.is-superseded .rp-step,
.rp-card.is-superseded .rp-time,
.rp-card.is-superseded .rp-mark { color: var(--ink-3); }
.rp-top { display: flex; align-items: center; gap: 8px; }
.rp-id { font-family: var(--mono); font-weight: 700; font-size: 13px; color: var(--violet); }
.rp-card.is-superseded .rp-id { color: var(--ink-3); }
.rp-step { font-size: 12px; color: var(--ink-2); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rp-time { font-size: 11.5px; color: var(--ink-3); font-variant-numeric: tabular-nums; margin-top: 3px; display: block; }
.rp-actions { margin-top: 9px; display: flex; align-items: center; gap: 8px; }
.btn-recover {
  font-size: 12.5px; font-weight: 600;
  padding: 5px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--violet);
  background: #fff; color: var(--violet);
}
.btn-recover:hover:not(:disabled) { background: var(--violet); color: #fff; }
.btn-recover:disabled { border-color: var(--line-strong); color: var(--lock); cursor: not-allowed; background: none; }
.rp-mark { font-size: 11.5px; color: var(--ink-3); }
.rp-empty, .ledger-empty {
  color: var(--ink-3);
  font-size: 12.5px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  padding: 14px;
  text-align: center;
  background: var(--surface-2);
}

.ledger { list-style: none; margin: 0; padding: 0; }
.ledger li {
  display: flex; gap: 10px;
  padding: 8px 2px;
  border-bottom: 1px dashed var(--line);
  font-size: 12.5px;
  align-items: flex-start;
}
.ledger li:last-child { border-bottom: none; }
.ledger .lg-icon { flex: none; width: 18px; text-align: center; }
.ledger .lg-body { flex: 1; color: var(--ink-2); }
.ledger .lg-time { display: block; font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
.ledger .is-recover .lg-body { color: var(--violet); }
.ledger .is-commit .lg-body { color: var(--ink); font-weight: 550; }
.ledger .is-reset .lg-body { color: var(--warn); }

/* ---------------- 确认门模态 ---------------- */
.overlay {
  position: fixed; inset: 0;
  background: rgba(15, 22, 34, .46);
  display: grid; place-items: center;
  z-index: 50;
  animation: fade .16s ease;
}
.gate {
  width: min(560px, calc(100vw - 48px));
  max-height: calc(100dvh - 64px);
  overflow-y: auto;
  background: var(--surface);
  border-radius: 14px;
  box-shadow: var(--shadow-2);
  border-top: 4px solid var(--danger);
  animation: rise .18s ease;
}
.gate.is-recover { border-top-color: var(--violet); }
.gate.is-reset { border-top-color: var(--warn); }
.gate-head { padding: 20px 24px 0; }
.gate-kicker {
  font-size: 11.5px; font-weight: 800; letter-spacing: .12em;
  text-transform: uppercase; color: var(--danger);
  display: flex; align-items: center; gap: 8px;
}
.gate.is-recover .gate-kicker { color: var(--violet); }
.gate.is-reset .gate-kicker { color: var(--warn); }
.gate-head h2 { font-size: 19px; margin-top: 6px; }
.gate-body { padding: 14px 24px 4px; }
.gate-consequence {
  background: var(--danger-bg);
  border: 1px solid var(--danger-line);
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  font-size: 13.5px; color: #6b1515;
}
.gate.is-recover .gate-consequence, .gate.is-reset .gate-consequence { background: var(--surface-2); border-color: var(--line); color: var(--ink-2); }
.gate-consequence b { color: var(--danger); }
.gate.is-recover .gate-consequence b { color: var(--violet); }
.gate-checkpoint {
  margin-top: 10px;
  font-size: 13px; color: var(--ink-2);
  display: flex; gap: 8px; align-items: center;
}
.gate-checkpoint .rp-ref { font-family: var(--mono); font-weight: 700; color: var(--violet); }
.gate-ack {
  display: flex; gap: 10px; align-items: flex-start;
  margin-top: 14px;
  font-size: 13.5px;
  cursor: pointer;
}
.gate-ack input { width: 16px; height: 16px; margin-top: 2px; accent-color: var(--danger); flex: none; cursor: pointer; }
.gate-pass { margin-top: 14px; }
.gate-pass label { display: block; font-size: 12.5px; font-weight: 650; color: var(--ink-2); margin-bottom: 6px; }
.gate-pass label code {
  font-family: var(--mono); color: var(--danger);
  background: var(--danger-bg); border: 1px solid var(--danger-line);
  padding: 0 6px; border-radius: 4px;
}
.gate-pass input {
  width: 100%;
  font-family: var(--mono);
  font-size: 15px;
  padding: 9px 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
}
.gate-pass input:focus { border-color: var(--accent); }
.gate-err { margin-top: 6px; font-size: 12px; color: var(--danger); min-height: 16px; }
.gate-foot {
  display: flex; justify-content: flex-end; gap: 10px;
  padding: 16px 24px 20px;
}
@keyframes fade { from { opacity: 0; } }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } }

/* ---------------- Toast ---------------- */
.toast {
  position: fixed; left: 50%; bottom: 26px;
  transform: translateX(-50%) translateY(16px);
  background: var(--ink); color: #fff;
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 13.5px;
  box-shadow: var(--shadow-2);
  opacity: 0; pointer-events: none;
  transition: opacity .18s ease, transform .18s ease;
  z-index: 60;
  max-width: min(620px, calc(100vw - 40px));
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast.is-warn { background: var(--warn); }
.toast.is-violet { background: var(--violet); }

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

@media (max-width: 1100px) {
  body { overflow: auto; height: auto; }
  .shell { grid-template-columns: 1fr; }
  .nav, .detail, .side { border: none; border-bottom: 1px solid var(--line); }
}

/* ============================================================
   发布关口 · Release Gate — spacious 控制台风格
   token 层（CSS 变量）→ 组件层，无外部依赖
   ============================================================ */
:root {
  --bg: #f3f5f8;
  --surface: #ffffff;
  --surface-2: #f8fafc;
  --ink: #17202e;
  --ink-2: #45536b;
  --ink-3: #5d6b82;
  --line: #e2e7ef;
  --line-strong: #cbd4e1;

  --accent: #2557d6;
  --accent-bg: #edf2fe;
  --ok: #17703a;
  --ok-bg: #e9f5ee;
  --ok-line: #bfe3cc;
  --warn: #9a4a08;
  --warn-bg: #fdf3e4;
  --warn-line: #f2d9ae;
  --danger: #b91f1f;
  --danger-bg: #fdeeee;
  --danger-line: #f3c6c6;
  --lock: #97a3b6;
  --lock-bg: #f1f3f7;
  --violet: #5b2fb8;
  --violet-bg: #f2ecfd;
  --violet-line: #ddccf7;

  --radius: 10px;
  --radius-sm: 7px;
  --shadow-1: 0 1px 2px rgba(23, 32, 46, .05), 0 1px 6px rgba(23, 32, 46, .04);
  --shadow-2: 0 8px 30px rgba(23, 32, 46, .16);

  --font: "Segoe UI", "PingFang SC", "Microsoft YaHei", "Noto Sans SC", system-ui, sans-serif;
  --mono: "Cascadia Code", Consolas, "JetBrains Mono", monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 14.5px;
  line-height: 1.55;
  color: var(--ink);
  background: var(--bg);
  display: grid;
  grid-template-rows: auto 1fr;
  height: 100dvh;
  overflow: hidden;
}

h1, h2, h3 { margin: 0; font-weight: 650; }
button { font-family: inherit; font-size: inherit; cursor: pointer; }
button:focus-visible, a:focus-visible, input:focus-visible, [tabindex]:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 4px;
}

/* ---------------- 顶栏：整体进度与完整性 ---------------- */
.topbar {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 12px 22px;
  background: var(--surface);
  border-bottom: 1px solid var(--line);
}
.brand { display: flex; align-items: center; gap: 12px; min-width: 0; }
.brand-mark {
  width: 36px; height: 36px;
  display: grid; place-items: center;
  background: var(--ink); color: #fff;
  border-radius: 9px; font-size: 18px;
}
.brand-text { display: flex; flex-direction: column; line-height: 1.25; }
.brand-text strong { font-size: 16px; }
.brand-sub { font-size: 12.5px; color: var(--ink-2); }

.badges { display: flex; gap: 10px; flex-wrap: wrap; margin-left: auto; }
.badge {
  display: inline-flex; align-items: center; gap: 7px;
  padding: 5px 12px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: var(--surface-2);
  font-size: 12.5px;
  color: var(--ink-2);
  white-space: nowrap;
}
.badge b { color: var(--ink); font-weight: 650; font-variant-numeric: tabular-nums; }
.badge .dot { width: 8px; height: 8px; border-radius: 50%; background: var(--lock); }
.badge.is-ok .dot { background: var(--ok); }
.badge.is-violet .dot { background: var(--violet); }
.badge.is-warn .dot { background: var(--warn); }
.badge.is-accent .dot { background: var(--accent); }

/* ---------------- 三栏骨架 ---------------- */
.shell {
  display: grid;
  grid-template-columns: 296px minmax(0, 1fr) 328px;
  min-height: 0;
}

/* ---------------- 左栏：阶段→步骤导航器 ---------------- */
.nav {
  background: var(--surface);
  border-right: 1px solid var(--line);
  overflow-y: auto;
  padding: 14px 12px 24px;
}
.nav-head {
  display: flex; align-items: baseline; justify-content: space-between;
  padding: 2px 8px 10px;
}
.nav-head h2 { font-size: 13px; letter-spacing: .06em; color: var(--ink-3); text-transform: uppercase; }
.nav-hint { font-size: 12px; color: var(--ink-3); font-variant-numeric: tabular-nums; }

.phase-label {
  display: flex; align-items: center; gap: 8px;
  margin: 16px 8px 6px;
  font-size: 12.5px; font-weight: 650; color: var(--ink-2);
}
.phase-label .phase-line { flex: 1; height: 1px; background: var(--line); }
.phase-label .phase-idx {
  width: 20px; height: 20px; border-radius: 6px;
  display: grid; place-items: center;
  background: var(--lock-bg); color: var(--ink-2);
  font-size: 11px; font-weight: 700;
}
.phase-label.is-open .phase-idx { background: var(--accent-bg); color: var(--accent); }
.phase-label.is-done .phase-idx { background: var(--ok-bg); color: var(--ok); }

.step-item {
  display: flex; align-items: center; gap: 10px;
  width: 100%;
  padding: 10px 10px;
  margin: 2px 0;
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  background: none;
  text-align: left;
  color: var(--ink);
  transition: background .12s ease;
}
.step-item:hover { background: var(--surface-2); }
.step-item.is-selected { background: var(--accent-bg); border-color: #c8d7f8; }
.step-item.is-locked .st-name { color: #4e5d76; font-weight: 500; }
.step-item .st-icon {
  flex: none;
  width: 24px; height: 24px;
  display: grid; place-items: center;
  border-radius: 50%;
  font-size: 12px; font-weight: 700;
  background: var(--lock-bg); color: var(--ink-2);
  border: 1.5px solid var(--line-strong);
}
.step-item.is-active .st-icon { background: #fff; color: var(--accent); border-color: var(--accent); }
.step-item.is-done .st-icon { background: var(--ok); color: #fff; border-color: var(--ok); }
.step-item.is-committed .st-icon { background: var(--violet); color: #fff; border-color: var(--violet); }
.step-item .st-body { flex: 1; min-width: 0; }
.step-item .st-name { display: block; font-weight: 550; font-size: 13.5px; }
.step-item .st-meta { display: block; font-size: 11.5px; color: var(--ink-3); }
.step-item .st-flag {
  flex: none;
  font-size: 11px; font-weight: 700;
  color: var(--danger);
  background: var(--danger-bg);
  border: 1px solid var(--danger-line);
  padding: 1px 7px; border-radius: 999px;
}
.step-item .st-rp {
  flex: none;
  font-size: 10.5px; font-weight: 700;
  color: var(--violet);
  background: var(--violet-bg);
  border: 1px solid var(--violet-line);
  padding: 1px 6px; border-radius: 999px;
  font-family: var(--mono);
}

/* ---------------- 中栏：步骤详情（dominant workspace） ---------------- */
.detail { overflow-y: auto; padding: 26px 34px 48px; }
.detail-inner { max-width: 720px; margin: 0 auto; }

.crumb { font-size: 12.5px; color: var(--ink-3); display: flex; gap: 8px; align-items: center; }
.detail h1 { font-size: 22px; margin: 8px 0 4px; letter-spacing: -.01em; }
.title-row { display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.tag {
  font-size: 11.5px; font-weight: 700;
  padding: 2px 9px; border-radius: 999px;
  border: 1px solid var(--line);
  color: var(--ink-2); background: var(--surface-2);
}
.tag.is-danger { color: var(--danger); background: var(--danger-bg); border-color: var(--danger-line); }
.tag.is-ok { color: var(--ok); background: var(--ok-bg); border-color: var(--ok-line); }
.tag.is-violet { color: var(--violet); background: var(--violet-bg); border-color: var(--violet-line); }
.tag.is-lock { color: var(--ink-3); background: var(--lock-bg); }

.why { color: var(--ink-2); margin: 10px 0 22px; max-width: 62ch; }

.section-label {
  font-size: 12.5px; font-weight: 700; letter-spacing: .05em;
  color: var(--ink-3); text-transform: uppercase;
  margin: 22px 0 10px;
  display: flex; align-items: center; gap: 8px;
}
.section-label .count { font-variant-numeric: tabular-nums; }

.checks { display: flex; flex-direction: column; gap: 8px; }
.check {
  display: flex; align-items: flex-start; gap: 12px;
  padding: 12px 14px;
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  box-shadow: var(--shadow-1);
  cursor: pointer;
}
.check:hover { border-color: var(--line-strong); }
.check input { margin: 0; width: 24px; height: 24px; accent-color: var(--accent); flex: none; cursor: pointer; }
.check .check-text { flex: 1; }
.check.is-checked .check-text { color: var(--ink-2); text-decoration: line-through; text-decoration-color: rgba(23,32,46,.25); }
.check.is-disabled { cursor: not-allowed; }
.check.is-disabled .check-text { color: var(--ink-2); }

/* 不可逆后果面板 */
.consequence {
  margin-top: 4px;
  border: 1px solid var(--warn-line);
  background: var(--warn-bg);
  border-radius: var(--radius);
  padding: 14px 16px;
}
.consequence h3 { font-size: 13.5px; color: var(--warn); display: flex; gap: 8px; align-items: center; }
.consequence p { margin: 8px 0 0; font-size: 13.5px; color: #5c4318; }
.consequence .recovery-hint {
  margin-top: 10px; padding-top: 10px;
  border-top: 1px dashed var(--warn-line);
  font-size: 13px; color: #5c4318;
}
.consequence .recovery-hint b { color: var(--warn); }

/* 操作区 */
.action-row {
  margin-top: 26px; padding-top: 20px;
  border-top: 1px solid var(--line);
  display: flex; align-items: center; gap: 14px; flex-wrap: wrap;
}
.btn {
  border: 1px solid transparent;
  border-radius: var(--radius-sm);
  padding: 10px 20px;
  font-weight: 600;
  font-size: 14px;
  transition: filter .12s ease, background .12s ease;
}
.btn-primary { background: var(--accent); color: #fff; }
.btn-primary:hover:not(:disabled) { filter: brightness(1.08); }
.btn-primary:disabled { background: var(--lock-bg); color: var(--ink-3); cursor: not-allowed; border-color: var(--line); }
.btn-danger { background: var(--danger); color: #fff; }
.btn-danger:hover:not(:disabled) { filter: brightness(1.06); }
.btn-danger:disabled { background: var(--danger-bg); color: #8a3d3d; cursor: not-allowed; border-color: var(--danger-line); }
.btn-ghost { background: none; border-color: var(--line-strong); color: var(--ink-2); padding: 8px 14px; font-size: 13px; }
.btn-ghost:hover { background: var(--surface-2); }
.action-hint { font-size: 12.5px; color: var(--ink-3); }

.done-note, .committed-note {
  margin-top: 26px;
  border-radius: var(--radius);
  padding: 14px 16px;
  font-size: 13.5px;
  display: flex; gap: 10px; align-items: flex-start;
}
.done-note { background: var(--ok-bg); border: 1px solid var(--ok-line); color: var(--ok); }
.committed-note { background: var(--violet-bg); border: 1px solid var(--violet-line); color: var(--violet); }
.committed-note .rp-ref { font-family: var(--mono); font-weight: 700; }
.locked-note {
  margin-top: 26px;
  background: var(--lock-bg); border: 1px solid var(--line);
  color: var(--ink-2); border-radius: var(--radius);
  padding: 14px 16px; font-size: 13.5px;
}

/* 完成横幅 */
.complete-banner {
  margin-bottom: 26px;
  border: 1px solid var(--ok-line);
  background: linear-gradient(180deg, #f2faf5, #e9f5ee);
  border-radius: 14px;
  padding: 22px 24px;
}
.complete-banner h2 { font-size: 19px; color: var(--ok); display: flex; gap: 10px; align-items: center; }
.complete-banner p { margin: 8px 0 0; color: var(--ink-2); max-width: 60ch; }
.complete-stats { display: flex; gap: 12px; margin-top: 16px; flex-wrap: wrap; }
.stat-chip {
  background: var(--surface);
  border: 1px solid var(--ok-line);
  border-radius: var(--radius-sm);
  padding: 8px 14px;
  font-size: 12.5px; color: var(--ink-2);
}
.stat-chip b { display: block; font-size: 16px; color: var(--ink); font-variant-numeric: tabular-nums; }

/* ---------------- 右栏：恢复点 + 执行记录 ---------------- */
.side {
  background: var(--surface);
  border-left: 1px solid var(--line);
  display: flex; flex-direction: column;
  min-height: 0;
}
.side-panel { padding: 14px 16px 10px; border-bottom: 1px solid var(--line); overflow-y: auto; }
.side-panel-grow { flex: 1; border-bottom: none; }
.side-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; margin-bottom: 10px; }
.side-head h2 { font-size: 13px; letter-spacing: .06em; color: var(--ink-3); text-transform: uppercase; }
.side-note { font-size: 11.5px; color: var(--ink-3); }

.rp-card {
  border: 1px solid var(--violet-line);
  background: var(--violet-bg);
  border-radius: var(--radius);
  padding: 11px 13px;
  margin-bottom: 9px;
}
.rp-card.is-superseded { background: var(--surface-2); border-color: var(--line); }
.rp-card.is-superseded .rp-id,
.rp-card.is-superseded .rp-step,
.rp-card.is-superseded .rp-time,
.rp-card.is-superseded .rp-mark { color: var(--ink-3); }
.rp-top { display: flex; align-items: center; gap: 8px; }
.rp-id { font-family: var(--mono); font-weight: 700; font-size: 13px; color: var(--violet); }
.rp-card.is-superseded .rp-id { color: var(--ink-3); }
.rp-step { font-size: 12px; color: var(--ink-2); flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.rp-time { font-size: 11.5px; color: var(--ink-3); font-variant-numeric: tabular-nums; margin-top: 3px; display: block; }
.rp-actions { margin-top: 9px; display: flex; align-items: center; gap: 8px; }
.btn-recover {
  font-size: 12.5px; font-weight: 600;
  padding: 5px 12px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--violet);
  background: #fff; color: var(--violet);
}
.btn-recover:hover:not(:disabled) { background: var(--violet); color: #fff; }
.btn-recover:disabled { border-color: var(--line-strong); color: var(--ink-3); cursor: not-allowed; background: none; }
.rp-mark { font-size: 11.5px; color: var(--ink-3); }
.rp-empty, .ledger-empty {
  color: var(--ink-3);
  font-size: 12.5px;
  border: 1px dashed var(--line-strong);
  border-radius: var(--radius);
  padding: 14px;
  text-align: center;
  background: var(--surface-2);
}

.ledger { list-style: none; margin: 0; padding: 0; }
.ledger li {
  display: flex; gap: 10px;
  padding: 8px 2px;
  border-bottom: 1px dashed var(--line);
  font-size: 12.5px;
  align-items: flex-start;
}
.ledger li:last-child { border-bottom: none; }
.ledger .lg-icon { flex: none; width: 18px; text-align: center; }
.ledger .lg-body { flex: 1; color: var(--ink-2); }
.ledger .lg-time { display: block; font-size: 11px; color: var(--ink-3); font-variant-numeric: tabular-nums; }
.ledger .is-recover .lg-body { color: var(--violet); }
.ledger .is-commit .lg-body { color: var(--ink); font-weight: 550; }
.ledger .is-reset .lg-body { color: var(--warn); }

/* ---------------- 确认门模态 ---------------- */
.overlay {
  position: fixed; inset: 0;
  background: rgba(15, 22, 34, .46);
  display: grid; place-items: center;
  z-index: 50;
  animation: fade .16s ease;
}
.gate {
  width: min(560px, calc(100vw - 48px));
  max-height: calc(100dvh - 64px);
  overflow-y: auto;
  background: var(--surface);
  border-radius: 14px;
  box-shadow: var(--shadow-2);
  border-top: 4px solid var(--danger);
  animation: rise .18s ease;
}
.gate.is-recover { border-top-color: var(--violet); }
.gate.is-reset { border-top-color: var(--warn); }
.gate-head { padding: 20px 24px 0; }
.gate-kicker {
  font-size: 11.5px; font-weight: 800; letter-spacing: .12em;
  text-transform: uppercase; color: var(--danger);
  display: flex; align-items: center; gap: 8px;
}
.gate.is-recover .gate-kicker { color: var(--violet); }
.gate.is-reset .gate-kicker { color: var(--warn); }
.gate-head h2 { font-size: 19px; margin-top: 6px; }
.gate-body { padding: 14px 24px 4px; }
.gate-consequence {
  background: var(--danger-bg);
  border: 1px solid var(--danger-line);
  border-radius: var(--radius-sm);
  padding: 12px 14px;
  font-size: 13.5px; color: #6b1515;
}
.gate.is-recover .gate-consequence, .gate.is-reset .gate-consequence { background: var(--surface-2); border-color: var(--line); color: var(--ink-2); }
.gate-consequence b { color: var(--danger); }
.gate.is-recover .gate-consequence b { color: var(--violet); }
.gate-checkpoint {
  margin-top: 10px;
  font-size: 13px; color: var(--ink-2);
  display: flex; gap: 8px; align-items: center;
}
.gate-checkpoint .rp-ref { font-family: var(--mono); font-weight: 700; color: var(--violet); }
.gate-ack {
  display: flex; gap: 10px; align-items: flex-start;
  margin-top: 14px;
  font-size: 13.5px;
  cursor: pointer;
}
.gate-ack input { width: 16px; height: 16px; margin-top: 2px; accent-color: var(--danger); flex: none; cursor: pointer; }
.gate-pass { margin-top: 14px; }
.gate-pass label { display: block; font-size: 12.5px; font-weight: 650; color: var(--ink-2); margin-bottom: 6px; }
.gate-pass label code {
  font-family: var(--mono); color: var(--danger);
  background: var(--danger-bg); border: 1px solid var(--danger-line);
  padding: 0 6px; border-radius: 4px;
}
.gate-pass input {
  width: 100%;
  font-family: var(--mono);
  font-size: 15px;
  padding: 9px 12px;
  border: 1px solid var(--line-strong);
  border-radius: var(--radius-sm);
  background: var(--surface);
}
.gate-pass input:focus { border-color: var(--accent); }
.gate-err { margin-top: 6px; font-size: 12px; color: var(--danger); min-height: 16px; }
.gate-foot {
  display: flex; justify-content: flex-end; gap: 10px;
  padding: 16px 24px 20px;
}
@keyframes fade { from { opacity: 0; } }
@keyframes rise { from { opacity: 0; transform: translateY(10px); } }

/* ---------------- Toast ---------------- */
.toast {
  position: fixed; left: 50%; bottom: 26px;
  transform: translateX(-50%) translateY(16px);
  background: var(--ink); color: #fff;
  padding: 10px 18px;
  border-radius: 999px;
  font-size: 13.5px;
  box-shadow: var(--shadow-2);
  opacity: 0; pointer-events: none;
  transition: opacity .18s ease, transform .18s ease;
  z-index: 60;
  max-width: min(620px, calc(100vw - 40px));
}
.toast.show { opacity: 1; transform: translateX(-50%) translateY(0); }
.toast.is-warn { background: var(--warn); }
.toast.is-violet { background: var(--violet); }

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

@media (max-width: 1100px) {
  body { overflow: auto; height: auto; }
  .shell { grid-template-columns: 1fr; }
  .nav, .detail, .side { border: none; border-bottom: 1px solid var(--line); }
}

